const pool = { open: true };
const listener = { accepting: true };
const worker = { running: true };
const log = [];

// A request that began before SIGTERM and must run one more query mid-drain.
function drainInFlightRequest() {
  if (!pool.open) {
    log.push('REQUEST FAILED: query hit a closed pool');
    return false;
  }
  log.push('request: in-flight query ok, response sent');
  return true;
}

function closeResource(name) {
  if (name === 'listener') { listener.accepting = false; log.push('closed: HTTP listener (refuse new)'); }
  else if (name === 'worker') { worker.running = false; log.push('closed: background worker'); }
  else if (name === 'pool') { pool.open = false; log.push('closed: DB pool'); }
}

// --- shutdown sequence (FIX THE ORDER) ---
closeResource('pool');      // BUG: pool first
drainInFlightRequest();     // in-flight request drains here
closeResource('listener');
closeResource('worker');
// --- end sequence ---

console.log(log.join('\n'));
